sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading)
        return;

    if (!newValue) {
        // Also runs when we clear an invalid date below – keep the error message visible.
        g_form.clearValue('days_to_due');
        return;
    }
    g_form.hideFieldMsg('due_date', true);

    var ga = new GlideAjax('x_snp_manager_su_0.MgrHubAjax');
    ga.addParam('sysparm_name', 'getDueInfo');
    ga.addParam('sysparm_due_date', newValue);
    ga.addParam('sysparm_opened_at', g_form.getValue('opened_at'));
    ga.getXMLAnswer(function(answer) {
        var info;
        try {
            info = JSON.parse(answer);
        } catch (e) {
            return; // the Business Rule still validates on save
        }
        if (!info.valid) {
            g_form.clearValue('due_date');
            g_form.showFieldMsg('due_date', getMessage('Due Date cannot be earlier than the Request Date.'), 'error');
            return;
        }
        g_form.setValue('days_to_due', info.daysToDue);
    });
}
